var e={remoteControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Invia comandi allo schermo FilaMind sulla stampante.`}},status:{ready:{t:0,b:{t:2,i:[{t:3}],s:`Bus comandi connesso`}},down:{t:0,b:{t:2,i:[{t:3}],s:`Connessione al bus comandi…`}}},show:{title:{t:0,b:{t:2,i:[{t:3}],s:`Mostra sullo schermo`}},status:{t:0,b:{t:2,i:[{t:3}],s:`Stato`}},control:{t:0,b:{t:2,i:[{t:3}],s:`Controllo`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`Impostazioni`}}},locate:{title:{t:0,b:{t:2,i:[{t:3}],s:`Individua lo schermo`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`Fai lampeggiare lo schermo per capire a quale stampante appartiene.`}},button:{t:0,b:{t:2,i:[{t:3}],s:`Individua schermo`}}},message:{title:{t:0,b:{t:2,i:[{t:3}],s:`Invia un messaggio`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`Scrivi un breve messaggio da mostrare sullo schermo…`}},level:{t:0,b:{t:2,i:[{t:3}],s:`Livello`}},info:{t:0,b:{t:2,i:[{t:3}],s:`Info`}},warn:{t:0,b:{t:2,i:[{t:3}],s:`Avviso`}},send:{t:0,b:{t:2,i:[{t:3}],s:`Invia`}}},sent:{t:0,b:{t:2,i:[{t:3}],s:`Inviato`}},help:{button:{t:0,b:{t:2,i:[{t:3}],s:`Aiuto`}},title:{t:0,b:{t:2,i:[{t:3}],s:`Controllo remoto — guida`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Chiudi`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`A cosa serve`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Questo pannello comanda da qui il touchscreen FilaMind sulla stampante: cambia la sua scheda, mostra un breve messaggio o fallo lampeggiare per capire di quale stampante si tratta. Sono solo indicazioni a schermo: non muovono mai la stampante né modificano alcuna impostazione.`}}},commands:{title:{t:0,b:{t:2,i:[{t:3}],s:`I comandi`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Mostra porta lo schermo alla scheda Stato, Controllo o Impostazioni. Individua fa lampeggiare lo schermo per qualche secondo. Messaggio mostra una breve nota (info o avviso). I comandi raggiungono qualsiasi schermo FilaMind su questa stampante; non viene inviato nulla mentre il bus comandi è ancora in connessione.`}}}}},requiresScreen:{t:0,b:{t:2,i:[{t:3}],s:`Questi controlli gestiscono lo schermo FilaMind sulla stampante. Installa FilaMind 3D su questa stampante per usarli.`}}}};export{e as default};